const ThreadSendTool = Tool.make("t3_thread_send", {
  description:
    "Send a message to any T3 thread in this environment. The target cannot have broader permission modes than the caller. Send review corrections, responses, and unresolved objections to the same childThreadId to preserve the reviewer's conversation. Use delegate_task for a fresh reviewer only after the main agent is satisfied and an unbiased check would help; do not replace the reviewer for ordinary follow-ups or disagreements. After the original task completes, a requested follow-up creates a fresh task in that child thread and returns taskId when it starts a turn or restarts a turn without its own task; its completion notifies the parent, and the original result stays unchanged. A steer that joins a running turn returns that turn's task, if it has one. mode='auto' starts an idle thread, steers a fully active turn, or queues behind a turn that is not yet steerable. Use queue for a separate follow-up turn, steer for an in-flight update, or restart to interrupt-and-restart the active turn. clientRequestId makes retries idempotent. In your reply, name the thread with its returned link verbatim.",
  parameters: OrchestratorMcpThreadSendInput,
  success: OrchestratorMcpThreadSendResult,
  failure: OrchestratorMcpFailure,
  failureMode: "return",
  dependencies,
})
  .annotate(Tool.Title, "Send to a T3 thread")
  .annotate(Tool.Destructive, true)
  .annotate(Tool.OpenWorld, true);

